-- TBC Anniversary dungeon quest content from user-supplied 46-page PDF:-- "TBC Classic Dungeon Quest Compendium", researched 20 October 2026.
-- This file only loads on TBC Anniversary; no Forever-only quests/items.
-- Quest minimums are PDF claims (unverified live); no fabricated XP/rewards.
local _, FDJ = ...
FDJ = FDJ or _G.ForeverDungeonJournal_NS
if not FDJ or not FDJ.IS_TBC_ANNIVERSARY then return end
FDJ.DB = FDJ.DB or {}
FDJ.QUEST_PREREQ_CHAINS = FDJ.QUEST_PREREQ_CHAINS or {}
FDJ.QUEST_PREREQ_DETAILS = FDJ.QUEST_PREREQ_DETAILS or {}

-- Idempotent merge of verified chapter entries into the existing dungeon UI.
local function MergeQuest(dungeonName, item)
    item.tbcCompendium = true
    item.tbcCompendium = true
    local dungeon = FDJ.DB[dungeonName]
    if not dungeon then return end
    dungeon.quests = dungeon.quests or {}
    for index, existing in ipairs(dungeon.quests) do
        if existing.id == item.id and (existing.faction or "Both") == (item.faction or "Both") then
            for field, value in pairs(item) do existing[field] = value end
            return
        end
    end
    table.insert(dungeon.quests, item)
end

